import{basename}from"node:path";import yargs from"yargs/yargs";import{hideBin}from"yargs/helpers";import{Text2ImagePipeline}from"openvino-genai-node";import{saveAsBMP}from"../image_utils.js";async function main(){const e=await yargs(hideBin(process.argv)).scriptName(basename(process.argv[1])).command("$0 <model_dir> <prompt>","Run Text2Image pipeline and save generated image as BMP file",(e=>e.positional("model_dir",{type:"string",describe:"Path to the converted image generation model directory",demandOption:!0}).positional("prompt",{type:"string",describe:"Prompt to generate images from",demandOption:!0}))).strict().help().parse(),i=await Text2ImagePipeline(e.model_dir,"CPU");const r=await i.generate(e.prompt,{width:512,height:512,num_inference_steps:20,num_images_per_prompt:1,callback:function(e,i){return process.stdout.write(`Step ${e+1}/${i}\r`),!1}});await saveAsBMP("image.bmp",r)}main().catch((e=>{console.error(e),process.exitCode=1}));